head.html:
#scc-tool{border:1px solid rgba(0,0,0,.12);border-radius:14px;padding:20px;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.06)}
#scc-input{width:100%;min-height:150px;box-sizing:border-box;font:16px/1.6 inherit;padding:14px;border:1px solid rgba(0,0,0,.18);border-radius:10px;resize:vertical}
#scc-input:focus{outline:2px solid #1ba4db;outline-offset:1px}
.scc-stats{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}
.scc-stat{flex:1 1 120px;border:1px solid rgba(0,0,0,.1);border-radius:10px;padding:12px 14px;background:#fafafa}
.scc-num{font-size:26px;font-weight:700;line-height:1.1}
.scc-lab{font-size:12px;text-transform:uppercase;letter-spacing:.05em;opacity:.6;margin-top:4px}
.scc-bar{height:6px;border-radius:99px;background:rgba(0,0,0,.08);margin-top:16px;overflow:hidden}
.scc-fill{height:100%;width:0;background:#2fae5d;transition:width .15s ease}
.scc-note{font-size:14px;line-height:1.6;margin-top:12px;opacity:.85}
.scc-warn{color:#b4531a}
.scc-row{display:flex;gap:10px;align-items:center;margin-top:12px;flex-wrap:wrap}
.scc-btn{font:14px inherit;padding:8px 14px;border-radius:99px;border:1px solid rgba(0,0,0,.2);background:#fff;cursor:pointer}
.scc-btn:hover{background:#f2f2f2}
